import { FilterLiveForm } from "ra-core";
import { Building, Tag, Users } from "lucide-react";
import { useGetIdentity } from "ra-core";
import { AutocompleteInput } from "@/components/admin/autocomplete-input";
import { ReferenceInput } from "@/components/admin/reference-input";
import { ToggleFilterButton } from "@/components/admin/toggle-filter-button";

import { useIsMobile } from "@/hooks/use-mobile";
import { useConfigurationContext } from "../root/ConfigurationContext";
import { ResponsiveFilters } from "../misc/ResponsiveFilters";
import { FilterCategory } from "../filters/FilterCategory";

export const DealListFilter = () => {
  const { dealCategories } = useConfigurationContext();
  const { identity } = useGetIdentity();
  const isMobile = useIsMobile();

  return (
    <ResponsiveFilters searchInput={{ placeholder: "Search deals..." }}>
      <FilterCategory label="Company" icon={<Building />}>
        <FilterLiveForm>
          <ReferenceInput source="company_id" reference="companies">
            <AutocompleteInput label={false} placeholder="Select Company" />
          </ReferenceInput>
        </FilterLiveForm>
      </FilterCategory>

      <FilterCategory label="Category" icon={<Tag />}>
        {dealCategories.map((cat) => (
          <ToggleFilterButton
            key={cat.value}
            className="w-auto md:w-full justify-between h-10 md:h-8"
            label={cat.label}
            value={{ category: cat.value }}
            size={isMobile ? "lg" : undefined}
          />
        ))}
      </FilterCategory>

      <FilterCategory icon={<Users />} label="Account Manager">
        <ToggleFilterButton
          className="w-full justify-between h-10 md:h-8"
          label={"Me"}
          value={{ sales_id: identity?.id }}
          size={isMobile ? "lg" : undefined}
        />
      </FilterCategory>
    </ResponsiveFilters>
  );
};
