import { useState } from "react";
import { useFormContext, useWatch } from "react-hook-form";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Plus, ListChecks } from "lucide-react";

import type { EscrowMilestone, MilestoneReferencePoint } from "../types";
import { MilestoneRow } from "./MilestoneRow";

export const MilestonesInput = () => {
  const { setValue, getValues } = useFormContext();
  const milestones: EscrowMilestone[] = useWatch({ name: "milestones" }) || [];
  const acceptanceDate = useWatch({ name: "acceptance_date" });
  const closingDate = useWatch({ name: "expected_closing_date" });

  const [addDialogOpen, setAddDialogOpen] = useState(false);
  const [newMilestone, setNewMilestone] = useState({
    name: "",
    rpa_reference: "",
    days_offset: 17,
    reference_point: "acceptance" as MilestoneReferencePoint,
  });

  const enabledCount = milestones.filter((m) => m.enabled).length;
  const completedCount = milestones.filter(
    (m) => m.enabled && m.completed_at,
  ).length;

  const handleMilestoneUpdate = (
    index: number,
    updates: Partial<EscrowMilestone>,
  ) => {
    const current = getValues("milestones") || [];
    const updated = [...current];
    updated[index] = { ...updated[index], ...updates };
    setValue("milestones", updated, { shouldDirty: true });
  };

  const handleAddMilestone = () => {
    if (!newMilestone.name.trim()) return;

    const milestone: EscrowMilestone = {
      id: crypto.randomUUID(),
      name: newMilestone.name.trim(),
      rpa_reference: newMilestone.rpa_reference.trim() || undefined,
      days_offset: newMilestone.days_offset,
      reference_point: newMilestone.reference_point,
      enabled: true,
    };

    const current = getValues("milestones") || [];
    setValue("milestones", [...current, milestone], { shouldDirty: true });

    // Reset form and close dialog
    setNewMilestone({
      name: "",
      rpa_reference: "",
      days_offset: 17,
      reference_point: "acceptance",
    });
    setAddDialogOpen(false);
  };

  if (milestones.length === 0) {
    return (
      <div className="text-sm text-muted-foreground py-4">
        No milestones configured. Milestones will be added when creating a new
        escrow.
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-3">
      <Accordion type="single" collapsible defaultValue="milestones">
        <AccordionItem value="milestones" className="border-none">
          <AccordionTrigger className="py-2 hover:no-underline">
            <div className="flex items-center gap-2">
              <ListChecks className="w-4 h-4" />
              <span className="text-base font-medium">Milestones</span>
              <span className="text-sm text-muted-foreground">
                ({completedCount}/{enabledCount} complete)
              </span>
            </div>
          </AccordionTrigger>
          <AccordionContent>
            <div className="flex flex-col gap-2 pt-2">
              {milestones.map((milestone, index) => (
                <MilestoneRow
                  key={milestone.id}
                  milestone={milestone}
                  acceptanceDate={acceptanceDate}
                  closingDate={closingDate}
                  onUpdate={(updates) => handleMilestoneUpdate(index, updates)}
                />
              ))}

              <Button
                type="button"
                variant="outline"
                size="sm"
                className="mt-2 w-fit"
                onClick={() => setAddDialogOpen(true)}
              >
                <Plus className="w-4 h-4 mr-1" />
                Add Custom Milestone
              </Button>
            </div>
          </AccordionContent>
        </AccordionItem>
      </Accordion>

      {/* Add Custom Milestone Dialog */}
      <Dialog open={addDialogOpen} onOpenChange={setAddDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Add Custom Milestone</DialogTitle>
          </DialogHeader>

          <div className="flex flex-col gap-4 py-4">
            <div className="flex flex-col gap-2">
              <Label htmlFor="milestone-name">Name *</Label>
              <Input
                id="milestone-name"
                value={newMilestone.name}
                onChange={(e) =>
                  setNewMilestone((prev) => ({ ...prev, name: e.target.value }))
                }
                placeholder="e.g., Tenant Estoppel Certificates"
              />
            </div>

            <div className="flex flex-col gap-2">
              <Label htmlFor="milestone-reference">
                Contract Reference (optional)
              </Label>
              <Input
                id="milestone-reference"
                value={newMilestone.rpa_reference}
                onChange={(e) =>
                  setNewMilestone((prev) => ({
                    ...prev,
                    rpa_reference: e.target.value,
                  }))
                }
                placeholder="e.g., RPA §14"
              />
            </div>

            <div className="flex gap-4">
              <div className="flex flex-col gap-2 flex-1">
                <Label htmlFor="milestone-days">Days</Label>
                <Input
                  id="milestone-days"
                  type="number"
                  min={0}
                  max={90}
                  value={newMilestone.days_offset}
                  onChange={(e) =>
                    setNewMilestone((prev) => ({
                      ...prev,
                      days_offset: parseInt(e.target.value) || 0,
                    }))
                  }
                />
              </div>

              <div className="flex flex-col gap-2 flex-1">
                <Label htmlFor="milestone-reference-point">Reference</Label>
                <Select
                  value={newMilestone.reference_point}
                  onValueChange={(value: MilestoneReferencePoint) =>
                    setNewMilestone((prev) => ({
                      ...prev,
                      reference_point: value,
                    }))
                  }
                >
                  <SelectTrigger id="milestone-reference-point">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="acceptance">After Acceptance</SelectItem>
                    <SelectItem value="closing">Before Closing</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => setAddDialogOpen(false)}
            >
              Cancel
            </Button>
            <Button
              type="button"
              onClick={handleAddMilestone}
              disabled={!newMilestone.name.trim()}
            >
              Add Milestone
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};
