import { useState, useMemo } from "react";
import { useFormContext, useWatch } from "react-hook-form";
import { useGetList, useGetOne } from "ra-core";
import { Check, ChevronsUpDown, Home, ExternalLink, X } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

import type { OfficeListing } from "../types";

const LISTING_PREVIEW_BASE_URL =
  "https://preview.allanrealestate.com/t/allan/search";

const formatPrice = (price: number | undefined | null) => {
  if (price == null) return "";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(price);
};

const statusVariant = (status: string): "default" | "secondary" | "outline" => {
  switch (status?.toLowerCase()) {
    case "active":
      return "default";
    case "pending":
      return "secondary";
    default:
      return "outline";
  }
};

/**
 * A form input for selecting a listing from office_listings.
 * Shows conditionally based on representation value (seller or both).
 * Stores the listing_key in the form.
 */
export const EscrowListingPicker = () => {
  const { setValue } = useFormContext();
  const representation = useWatch({ name: "representation" });
  const listingKey = useWatch({ name: "listing_key" });

  // Only show for seller or both representation
  if (representation !== "seller" && representation !== "both") {
    return null;
  }

  return (
    <div className="flex flex-col gap-2">
      <Label className="text-sm font-medium">Linked Listing</Label>
      {listingKey ? (
        <LinkedListingDisplay
          listingKey={listingKey}
          onRemove={() => setValue("listing_key", null)}
        />
      ) : (
        <ListingSelector onSelect={(key) => setValue("listing_key", key)} />
      )}
    </div>
  );
};

const LinkedListingDisplay = ({
  listingKey,
  onRemove,
}: {
  listingKey: string;
  onRemove: () => void;
}) => {
  const { data: listing, isPending } = useGetOne<
    OfficeListing & { id: string }
  >("office_listings", { id: listingKey }, { enabled: !!listingKey });

  if (isPending) {
    return (
      <div className="p-2 border rounded-md bg-muted/30">
        <p className="text-sm text-muted-foreground">Loading listing...</p>
      </div>
    );
  }

  if (!listing) {
    return (
      <div className="flex items-center justify-between p-2 border rounded-md bg-muted/30">
        <p className="text-sm text-muted-foreground italic">
          Listing no longer available (key: {listingKey})
        </p>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={onRemove}
          className="h-6 w-6 p-0"
        >
          <X className="w-4 h-4" />
        </Button>
      </div>
    );
  }

  return (
    <div className="flex items-start justify-between gap-1 p-2 border rounded-md bg-muted/30">
      <div className="flex flex-col gap-0.5 min-w-0">
        <div className="flex items-center gap-1.5">
          <Home className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
          <a
            href={`${LISTING_PREVIEW_BASE_URL}/${listing.listing_key}`}
            target="_blank"
            rel="noopener noreferrer"
            className="text-sm underline hover:no-underline text-primary truncate"
            title={listing.unparsed_address}
          >
            {listing.unparsed_address}
          </a>
          <ExternalLink className="w-3 h-3 text-muted-foreground shrink-0" />
        </div>
        <div className="flex items-center gap-2 pl-5">
          <span className="text-xs text-muted-foreground">
            {formatPrice(listing.list_price)}
          </span>
          <Badge
            variant={statusVariant(listing.standard_status)}
            className="text-[10px] px-1.5 py-0"
          >
            {listing.standard_status}
          </Badge>
        </div>
      </div>
      <Button
        type="button"
        variant="ghost"
        size="sm"
        onClick={onRemove}
        className="h-6 w-6 p-0 shrink-0"
      >
        <X className="w-4 h-4" />
      </Button>
    </div>
  );
};

const ListingSelector = ({
  onSelect,
}: {
  onSelect: (listingKey: string) => void;
}) => {
  const [open, setOpen] = useState(false);
  const [selected, setSelected] = useState<
    (OfficeListing & { id: string }) | null
  >(null);

  const { data: allListings } = useGetList<OfficeListing & { id: string }>(
    "office_listings",
    {
      sort: { field: "unparsed_address", order: "ASC" },
      pagination: { page: 1, perPage: 100 },
    },
  );

  const listings = useMemo(() => allListings ?? [], [allListings]);

  const handleSelect = (listing: OfficeListing & { id: string }) => {
    setSelected(listing);
    setOpen(false);
    onSelect(listing.listing_key);
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className="justify-between font-normal text-left h-auto min-h-9 w-full"
        >
          <span className="truncate text-muted-foreground">
            {selected
              ? selected.unparsed_address
              : "Search by address or MLS#..."}
          </span>
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[300px] p-0" align="start">
        <Command>
          <CommandInput placeholder="Search listings..." />
          <CommandList>
            <CommandEmpty>No listings found.</CommandEmpty>
            <CommandGroup>
              {listings.map((listing) => (
                <CommandItem
                  key={listing.listing_key}
                  value={`${listing.unparsed_address} ${listing.listing_id}`}
                  onSelect={() => handleSelect(listing)}
                >
                  <Check
                    className={cn(
                      "mr-2 h-4 w-4 shrink-0",
                      selected?.listing_key === listing.listing_key
                        ? "opacity-100"
                        : "opacity-0",
                    )}
                  />
                  <div className="flex flex-col min-w-0">
                    <span className="text-sm truncate">
                      {listing.unparsed_address}
                    </span>
                    <span className="text-xs text-muted-foreground">
                      MLS# {listing.listing_id} &middot;{" "}
                      {formatPrice(listing.list_price)} &middot;{" "}
                      {listing.standard_status}
                    </span>
                  </div>
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
};
