import { useState, useEffect, useMemo } from "react";
import { addDays, subDays, format, parseISO, isValid } from "date-fns";
import { Switch } from "@/components/ui/switch";
import { Slider } from "@/components/ui/slider";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Calendar, Clock } from "lucide-react";

import type { EscrowMilestone } from "../types";

interface MilestoneRowProps {
  milestone: EscrowMilestone;
  acceptanceDate?: string;
  closingDate?: string;
  onUpdate: (updates: Partial<EscrowMilestone>) => void;
}

const calculateMilestoneDate = (
  milestone: EscrowMilestone,
  acceptanceDate?: string,
  closingDate?: string,
): Date | null => {
  if (milestone.date_override) {
    const parsed = parseISO(milestone.date_override);
    return isValid(parsed) ? parsed : null;
  }

  const refDateStr =
    milestone.reference_point === "acceptance" ? acceptanceDate : closingDate;
  if (!refDateStr) return null;

  const refDate = parseISO(refDateStr);
  if (!isValid(refDate)) return null;

  if (milestone.reference_point === "closing") {
    return subDays(refDate, Math.abs(milestone.days_offset));
  }
  return addDays(refDate, milestone.days_offset);
};

export const MilestoneRow = ({
  milestone,
  acceptanceDate,
  closingDate,
  onUpdate,
}: MilestoneRowProps) => {
  const [showDateOverride, setShowDateOverride] = useState(
    !!milestone.date_override,
  );

  useEffect(() => {
    if (milestone.date_override) {
      setShowDateOverride(true);
    }
  }, [milestone.date_override]);

  const calculatedDate = useMemo(
    () => calculateMilestoneDate(milestone, acceptanceDate, closingDate),
    [milestone, acceptanceDate, closingDate],
  );

  const handleToggleDateOverride = (checked: boolean) => {
    setShowDateOverride(checked);
    if (!checked) {
      onUpdate({ date_override: undefined });
    } else if (calculatedDate) {
      // Pre-fill with calculated date when switching to override
      onUpdate({ date_override: format(calculatedDate, "yyyy-MM-dd") });
    }
  };

  const handleToggleEnabled = (checked: boolean) => {
    onUpdate({ enabled: checked });
  };

  const handleDaysChange = (value: number[]) => {
    onUpdate({ days_offset: value[0] });
  };

  const handleDateOverrideChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onUpdate({ date_override: e.target.value || undefined });
  };

  const handleToggleCompleted = (checked: boolean) => {
    onUpdate({
      completed_at: checked ? new Date().toISOString() : undefined,
    });
  };

  const referenceLabel =
    milestone.reference_point === "closing"
      ? "days before closing"
      : "days after acceptance";

  return (
    <div
      className={`flex flex-col gap-2 p-3 rounded-md border ${
        milestone.enabled ? "bg-background" : "bg-muted/30 opacity-60"
      }`}
    >
      {/* Header row: Enable toggle, name, completion checkbox */}
      <div className="flex items-center gap-3">
        <Switch
          checked={milestone.enabled}
          onCheckedChange={handleToggleEnabled}
          className="shrink-0"
        />

        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span
              className={`font-medium text-sm truncate ${
                milestone.completed_at
                  ? "line-through text-muted-foreground"
                  : ""
              }`}
            >
              {milestone.name}
            </span>
            {milestone.rpa_reference && (
              <span className="text-xs text-muted-foreground shrink-0">
                {milestone.rpa_reference}
              </span>
            )}
          </div>
        </div>

        {milestone.enabled && (
          <div className="flex items-center gap-2 shrink-0">
            <Checkbox
              id={`completed-${milestone.id}`}
              checked={!!milestone.completed_at}
              onCheckedChange={handleToggleCompleted}
            />
            <Label
              htmlFor={`completed-${milestone.id}`}
              className="text-xs text-muted-foreground"
            >
              Done
            </Label>
          </div>
        )}
      </div>

      {/* Controls row: Only show when enabled */}
      {milestone.enabled && (
        <div className="flex items-center gap-4 pl-12">
          {/* Date mode toggle */}
          <div className="flex items-center gap-2">
            <Clock className="w-3 h-3 text-muted-foreground" />
            <Switch
              checked={showDateOverride}
              onCheckedChange={handleToggleDateOverride}
              className="scale-75"
            />
            <Calendar className="w-3 h-3 text-muted-foreground" />
          </div>

          {showDateOverride ? (
            /* Date override input */
            <Input
              type="date"
              value={milestone.date_override || ""}
              onChange={handleDateOverrideChange}
              className="w-40 h-8 text-sm"
            />
          ) : (
            /* Days slider */
            <div className="flex items-center gap-3 flex-1">
              <Slider
                value={[milestone.days_offset]}
                onValueChange={handleDaysChange}
                min={0}
                max={30}
                step={1}
                className="flex-1 max-w-32"
              />
              <span className="text-xs text-muted-foreground whitespace-nowrap w-36">
                {milestone.days_offset} {referenceLabel}
              </span>
            </div>
          )}

          {/* Calculated date display */}
          {calculatedDate && (
            <span className="text-sm font-medium ml-auto">
              {format(calculatedDate, "MMM d, yyyy")}
            </span>
          )}
          {!calculatedDate && !showDateOverride && (
            <span className="text-xs text-muted-foreground ml-auto">
              {milestone.reference_point === "acceptance"
                ? "Set acceptance date"
                : "Set closing date"}
            </span>
          )}
        </div>
      )}
    </div>
  );
};
